// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 a1, uint256 a2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        a1 = bound(a1, 1, 1e30);
        a2 = bound(a2, 1, 1e30);
        vm.assume(a1 + a2 >= a1 && a1 + a2 >= a2);

        vm.deal(actor, a1 + a2);

        vm.prank(actor);
        c.Put{value: a1}(0);
        vm.prank(actor);
        c.Put{value: a2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == a1 + a2);
    }
}
